-- Compact, then Z-Order, then V-Order in one pass
OPTIMIZE dbo.sales ZORDER BY (order_date, region) VORDER;

-- Liquid clustering: define once, applied on every OPTIMIZE
ALTER TABLE dbo.sales_lc CLUSTER BY (order_date, region);
OPTIMIZE dbo.sales_lc;

-- Table-level V-Order default for future writes
ALTER TABLE dbo.sales SET TBLPROPERTIES ("delta.parquet.vorder.enabled" = "true");

-- List files older than 7 days that VACUUM would delete
VACUUM dbo.sales RETAIN 168 HOURS DRY RUN;

-- Single-column statistics after a large load
CREATE STATISTICS DimCustomer_CustomerKey_FullScan
ON dbo.DimCustomer (CustomerKey) WITH FULLSCAN;
UPDATE STATISTICS dbo.DimCustomer (DimCustomer_CustomerKey_FullScan) WITH FULLSCAN;

-- Result set caching is on by default; check the item setting
SELECT name, is_result_set_caching_on FROM sys.databases WHERE database_id = db_id();

-- Bypass the cache for one query (debugging, A/B tests)
SELECT Region, SUM(Amount) FROM dbo.FactSales GROUP BY Region
OPTION ( USE HINT ('DISABLE_RESULT_SET_CACHE') );

-- 2 = cache hit, 1 = cache created, 0 = not eligible
SELECT result_cache_hit, command FROM queryinsights.exec_requests_history
ORDER BY submit_time DESC;

// Keep the last 30 days in hot cache
.alter table Telemetry policy caching hot = 30d

// Delete rows older than 90 days
.alter-merge table Telemetry policy retention softdelete = 90d recoverability = disabled

// Transform RawEvents into Telemetry at ingestion time
.alter table Telemetry policy update
@'[{ "IsEnabled": true, "Source": "RawEvents", "Query": "ParseRaw()", "IsTransactional": true, "PropagateIngestionProperties": false}]'

// Keep the raw landing table empty after the update policy runs
.alter-merge table RawEvents policy retention softdelete = 0s
